#' Measurement invariance of the bifactor-plus-wording model across groups
#'
#' Checks whether the bifactor model with a wording factor functions equally
#' across groups before the group-specific indices of \code{\link{pure_value}}
#' are compared. For ordinal items the sequence follows Wu and Estabrook (2016):
#' configural, equal thresholds, and equal thresholds and loadings, with model
#' syntax generated by \code{semTools::measEq.syntax()} (delta parameterization,
#' standardized latent variables, factors kept orthogonal). For continuous items
#' the sequence is configural, equal loadings, and equal loadings and
#' intercepts. Nested models are compared with the scaled chi-square difference
#' test and with changes in CFI and RMSEA. For ordinal items, a response
#' category that is empty in any group is merged with its neighbor toward the
#' middle of the scale in all groups, and the affected items are reported.
#'
#' @inheritParams pure_value
#' @param group Name of the grouping variable (required).
#' @param cfi_cut,rmsea_cut Thresholds for the change in CFI (decrease) and
#'   RMSEA (increase) used to label a step as supported; defaults follow Chen
#'   (2007).
#' @return An object of class \code{pure_invariance}: a list with \code{table}
#'   (fit of each step, whether its solution is proper, and the comparison with
#'   the preceding step) and the fitted \code{models}. Comparisons involving an
#'   improper solution are not labeled as supported or unsupported.
#' @references Chen, F. F. (2007). Sensitivity of goodness of fit indexes to lack
#'   of measurement invariance. \emph{Structural Equation Modeling, 14}(3),
#'   464--504. \doi{10.1080/10705510701301834}
#'
#'   Wu, H., & Estabrook, R. (2016). Identification of confirmatory factor
#'   analysis models of different levels of invariance for ordered categorical
#'   outcomes. \emph{Psychometrika, 81}(4), 1014--1045.
#'   \doi{10.1007/s11336-016-9506-0}
#' @examples
#' \donttest{
#' if (requireNamespace("semTools", quietly = TRUE)) {
#'   set.seed(3)
#'   sim <- simulate_pure(n = 800)
#'   d <- sim$data
#'   d$grp <- rep(c("a", "b"), each = 400)
#'   pure_invariance(d, sim$facets, sim$method, group = "grp")
#' }
#' }
#' @export
pure_invariance <- function(data, facets, method, group, ordered = TRUE,
                            cfi_cut = 0.010, rmsea_cut = 0.015, ...) {
  check_facets(facets, method)
  if (missing(group) || !group %in% names(data))
    stop("`group` must name a variable in `data`.", call. = FALSE)
  items <- unlist(facets, use.names = FALSE)
  data <- data[!is.na(data[[group]]), , drop = FALSE]
  data[[group]] <- droplevels(as.factor(data[[group]]))
  if (nlevels(data[[group]]) < 2) stop("`group` needs at least two levels.", call. = FALSE)
  mod <- pure_syntax(facets, method, "bifactor_method")
  collapsed <- character(0)
  if (ordered) {
    cl <- collapse_empty(data, items, group)
    data <- cl$data; collapsed <- cl$collapsed
    if (!requireNamespace("semTools", quietly = TRUE))
      stop("Package 'semTools' is required for ordinal invariance testing.", call. = FALSE)
    steps <- list(configural = character(0), thresholds = "thresholds",
                  loadings = c("thresholds", "loadings"))
    fits <- lapply(steps, function(eq) {
      syn <- suppressMessages(suppressWarnings(semTools::measEq.syntax(
        configural.model = mod, data = data, ordered = items, parameterization = "delta",
        ID.fac = "std.lv", ID.cat = "Wu.Estabrook.2016", group = group,
        group.equal = eq, orthogonal = TRUE, ...)))
      args <- list(model = as.character(syn), data = data, ordered = items, group = group,
                   estimator = "WLSMV", parameterization = "delta", ...)
      suppressWarnings(do.call("cfa", args, envir = asNamespace("lavaan")))
    })
    idx <- c("chisq.scaled", "df.scaled", "cfi.scaled", "rmsea.scaled")
  } else {
    steps <- list(configural = character(0), loadings = "loadings",
                  intercepts = c("loadings", "intercepts"))
    fits <- lapply(steps, function(eq) {
      args <- list(model = mod, data = data, group = group, std.lv = TRUE,
                   orthogonal = TRUE, group.equal = eq, ...)
      suppressWarnings(do.call("cfa", args, envir = asNamespace("lavaan")))
    })
    idx <- c("chisq", "df", "cfi", "rmsea")
  }
  conv <- vapply(fits, lavaan::lavInspect, TRUE, what = "converged")
  proper <- vapply(fits, function(f) {
    st <- lavaan::lavInspect(f, "std")
    if (!is.null(st$lambda)) st <- list(st)
    all(vapply(st, function(b) min(diag(b$theta)) > 0, TRUE))
  }, TRUE)
  if (!all(conv)) warning("Not all invariance models converged: ",
                          paste(names(fits)[!conv], collapse = ", "), call. = FALSE)
  fm <- t(vapply(fits, function(f) unname(lavaan::fitMeasures(f, idx)), numeric(4)))
  tab <- data.frame(step = names(fits), chisq = fm[, 1], df = fm[, 2], CFI = fm[, 3],
                    RMSEA = fm[, 4], d_chisq = NA_real_, d_df = NA_real_, p = NA_real_,
                    d_CFI = NA_real_, d_RMSEA = NA_real_, supported = NA, proper = proper,
                    row.names = NULL)
  for (k in 2:length(fits)) {
    lrt <- tryCatch(suppressWarnings(lavaan::lavTestLRT(fits[[k - 1]], fits[[k]])),
                    error = function(e) NULL)
    if (!is.null(lrt)) {
      tab$d_chisq[k] <- lrt[2, "Chisq diff"]; tab$d_df[k] <- lrt[2, "Df diff"]
      tab$p[k] <- lrt[2, "Pr(>Chisq)"]
    }
    tab$d_CFI[k] <- tab$CFI[k] - tab$CFI[k - 1]
    tab$d_RMSEA[k] <- tab$RMSEA[k] - tab$RMSEA[k - 1]
    tab$supported[k] <- if (proper[k] && proper[k - 1] && !is.na(tab$d_CFI[k]))
      tab$d_CFI[k] >= -cfi_cut && tab$d_RMSEA[k] <= rmsea_cut else NA
  }
  out <- list(table = tab, models = fits, group = group, ordered = ordered,
              collapsed = collapsed,
              n = table(data[[group]]), cuts = c(cfi = cfi_cut, rmsea = rmsea_cut))
  class(out) <- "pure_invariance"
  out
}

#' @export
print.pure_invariance <- function(x, digits = 3, ...) {
  cat("Invariance of the bifactor-plus-wording model across '", x$group, "' (",
      paste(names(x$n), x$n, sep = " = ", collapse = ", "), ")\n", sep = "")
  tab <- x$table
  num <- vapply(tab, is.numeric, TRUE)
  tab[num] <- lapply(tab[num], round, digits)
  print(tab, row.names = FALSE)
  cat("Supported: change in CFI >= -", x$cuts[["cfi"]], " and change in RMSEA <= ",
      x$cuts[["rmsea"]], " relative to the preceding step.\n", sep = "")
  if (any(!x$table$proper))
    cat("Improper solution (negative residual variance) at step(s): ",
        paste(x$table$step[!x$table$proper], collapse = ", "),
        "; comparisons involving these steps are not evaluated.\n", sep = "")
  if (length(x$collapsed))
    cat("Categories empty in at least one group were merged with an adjacent category for: ",
        paste(x$collapsed, collapse = ", "), "\n", sep = "")
  invisible(x)
}

# Merge response categories that are empty in at least one group with the
# adjacent category nearer the middle of the scale, for every group alike.
collapse_empty <- function(data, items, group) {
  collapsed <- character(0)
  g <- data[[group]]
  for (it in items) {
    x <- data[[it]]
    repeat {
      lev <- sort(unique(x[!is.na(x)]))
      if (length(lev) < 3) break
      tab <- table(factor(x, levels = lev), g)
      empty <- which(apply(tab, 1, function(r) any(r == 0)))
      if (!length(empty)) break
      k <- empty[1]
      mid <- (length(lev) + 1) / 2
      to <- if (k < mid) lev[k + 1] else lev[k - 1]
      x[x == lev[k]] <- to
      collapsed <- union(collapsed, it)
    }
    data[[it]] <- x
  }
  list(data = data, collapsed = collapsed)
}
